pub struct B_vacates { o1: Bw, o2: Bw }
impl B_vacates {
    pub fn new() -> B_vacates { B_vacates { o1: Bw::new(4096), o2: Bw::new(4096) } }
    #[inline] pub fn set_t(&mut self, t: [usize; 3]) -> bool {
        if !self.o2.set((t[0]) * 64 + t[1], t[2]) { return false; }
        self.o1.set((t[0]) * 64 + t[2], t[1]);
        true
    }
    #[inline] pub fn has_t(&self, t: [usize; 3]) -> bool { (self.o2.w[(t[0]) * 64 + t[1]] >> t[2]) & 1 == 1 }
    /// Or the word `v` into the word `key` of the last tile's orientation (the tiles before it numbered as that orientation numbers them); the bits that were not set.
    pub fn or_word(&mut self, key: usize, v: u64) -> u64 {
        let nb = self.o2.or(key, v);
        if nb != 0 {
            let mut t = [0usize; 3];
            let mut rm = key;
            t[1] = rm % 64; rm /= 64;
            t[0] = rm % 64; rm /= 64;
            let (bf1, af1) = ((t[0]) * 64 + 0, t[1]);
            let mut b = nb;
            while b != 0 { let p = b.trailing_zeros() as usize; b &= b - 1;
                self.o1.set(bf1 + p * 1, af1);
            }
        }
        nb
    }
    pub fn tiles_of(r: &[u32; 6]) -> Option<[usize; 3]> {
        let a0 = [ordof(&OS1, r[0]), ordof(&OS4, r[1])];
        if a0.iter().any(|&x| x == NONE) { return None; }
        let a1 = [ordof(&OS1, r[2]), ordof(&OS4, r[3])];
        if a1.iter().any(|&x| x == NONE) { return None; }
        let a2 = [ordof(&OS1, r[4]), ordof(&OS4, r[5])];
        if a2.iter().any(|&x| x == NONE) { return None; }
        Some([a0[0] * 8 + a0[1], a1[0] * 8 + a1[1], a2[0] * 8 + a2[1]])
    }
    pub fn row_of(t: [usize; 3]) -> [u32; 6] {
        let mut r = [0u32; 6];
        r[0] = SS1[t[0] / 8];
        r[1] = SS4[t[0] % 8];
        r[2] = SS1[t[1] / 8];
        r[3] = SS4[t[1] % 8];
        r[4] = SS1[t[2] / 8];
        r[5] = SS4[t[2] % 8];
        r
    }
    pub fn add(&mut self, r: [u32; 6]) -> bool { let t = Self::tiles_of(&r).expect("a row outside the sorts of its relation"); self.set_t(t) }
    pub fn has(&self, r: &[u32; 6]) -> bool { match Self::tiles_of(r) { Some(t) => self.has_t(t), None => false } }
    pub fn rows_all(&self) -> Vec<[u32; 6]> {
        let mut out = vec![];
        for &key in self.o2.nz.iter() {
            let mut t = [0usize; 3];
            let mut rm = key as usize;
            t[1] = rm % 64; rm /= 64;
            t[0] = rm % 64; rm /= 64;
            let mut b = self.o2.w[key as usize];
            while b != 0 { t[2] = b.trailing_zeros() as usize; b &= b - 1; out.push(Self::row_of(t)); }
        }
        out
    }
    pub fn get(&self, _i: usize, key: &[u32; 6]) -> Vec<[u32; 6]> { self.rows_all().into_iter().filter(|r| (0..6).all(|p| key[p] == FREE || r[p] == key[p])).collect() }
    pub fn is_empty(&self) -> bool { self.o2.nz.is_empty() }
    pub fn clear(&mut self) { self.o1.clear(); self.o2.clear(); }
}
