fn c8v0(s: &St, d: &mut Dy, tm: &mut Terms, dw: &mut Dw) -> u64 {
    let mut made = 0u64;
    for ti1 in 0..s.r_home_rank.o1.nz.len() {
        let ix1 = s.r_home_rank.o1.nz[ti1] as usize;
        let mut w1 = s.r_home_rank.o1.w[ix1];
        let mut rm1 = ix1;
        let t1_0 = rm1;
        let v0 = t1_0;
        if w1 == 0 { continue; }
        let mut m2 = w1;
        while m2 != 0 {
            let b2 = m2.trailing_zeros() as usize;
            m2 &= m2 - 1;
            let v1 = b2;
            let mut w3 = d.r_occupied.o0.w[0];
            w3 &= MK2_1[v1];
            if w3 == 0 { continue; }
            let mut m4 = w3;
            while m4 != 0 {
                let b4 = m4.trailing_zeros() as usize;
                m4 &= m4 - 1;
                let v2 = b4 / 8;
                let mut w5 = s.r_castling_empty.o0.w[v2];
                let mut m6 = w5;
                while m6 != 0 {
                    let b6 = m6.trailing_zeros() as usize;
                    m6 &= m6 - 1;
                    let v3 = b6;
                    let tt7: [usize; 1] = [(v0) * 2 + v3];
                    if d.r_castle_blocked.set_t(tt7) { made += 1; }
                }
            }
        }
    }
    made
}
