fn c8(s: &St, d: &mut Dy, tm: &mut Terms, dw: &mut Dw) -> u64 {
    let mut best = 0usize; let mut best_e = u64::MAX;
    { let mut p = 1u64; let mut e = 0u64;
      p = p.saturating_mul((((s.r_home_rank.o1.nz.len()) * 2) as u64).max(1)); e = e.saturating_add(p);
      p = p.saturating_mul((((d.r_occupied.o0.w[0].count_ones() as usize)) as u64).max(1)); e = e.saturating_add(p);
      p = p.saturating_mul((((1) * 2) as u64).max(1)); e = e.saturating_add(p);
      if e < best_e { best_e = e; best = 0; } }
    { let mut p = 1u64; let mut e = 0u64;
      p = p.saturating_mul((((d.r_occupied.o0.w[0].count_ones() as usize)) as u64).max(1)); e = e.saturating_add(p);
      p = p.saturating_mul((((1) * 2) as u64).max(1)); e = e.saturating_add(p);
      p = p.saturating_mul((((1) * 2) as u64).max(1)); e = e.saturating_add(p);
      if e < best_e { best_e = e; best = 1; } }
    { let mut p = 1u64; let mut e = 0u64;
      p = p.saturating_mul((((s.r_castling_empty.o1.nz.len()) * 2) as u64).max(1)); e = e.saturating_add(p);
      p = p.saturating_mul((((d.r_occupied.o0.w[0].count_ones() as usize)) as u64).max(1)); e = e.saturating_add(p);
      p = p.saturating_mul((((1) * 2) as u64).max(1)); e = e.saturating_add(p);
      if e < best_e { best_e = e; best = 2; } }
    match best {
        0 => c8v0(s, d, tm, dw),
        1 => c8v1(s, d, tm, dw),
        _ => c8v2(s, d, tm, dw),
    }
}
