        n.f_cell = { let mut v: Vec<[u32; 4]> = vec![]; for r in &s.f_cell { if (!d.r_lifted.has(&[r[0], r[1]]) && !d.r_landed.has(&[r[0], r[1]])) { v.push(*r); } } v.extend_from_slice(&d.r_next_cell.order); v };
