impl State {
    /// Copy `o` into this state, keeping the memory of the lists it holds.
    pub fn assign(&mut self, o: &State) {
        self.f_castling_right.clear(); self.f_castling_right.extend_from_slice(&o.f_castling_right);
        self.f_cell.clear(); self.f_cell.extend_from_slice(&o.f_cell);
        self.f_control.clear(); self.f_control.extend_from_slice(&o.f_control);
        self.f_ep_square.clear(); self.f_ep_square.extend_from_slice(&o.f_ep_square);
        self.f_halfmove.clear(); self.f_halfmove.extend_from_slice(&o.f_halfmove);
    }
}
impl State {
    pub fn sort(&mut self) {
        self.f_castling_right.sort(); self.f_castling_right.dedup();
        self.f_cell.sort(); self.f_cell.dedup();
        self.f_control.sort(); self.f_control.dedup();
        self.f_ep_square.sort(); self.f_ep_square.dedup();
        self.f_halfmove.sort(); self.f_halfmove.dedup();
    }
}
